-- Blue Haven: ejecutar en Supabase SQL Editor como propietario del proyecto.
-- No elimina datos existentes. Supabase Auth administra las contraseñas.
begin;

create table public.perfiles (
  usuario_id uuid primary key references auth.users(id) on delete cascade,
  usuario text not null check (char_length(usuario) between 1 and 50),
  dinero bigint not null default 0 check (dinero >= 0),
  tiene_bambu boolean not null default false,
  creado_en timestamptz not null default now()
);
create table public.peces (
  id bigint generated by default as identity primary key,
  nombre text not null unique,
  rareza integer not null check (rareza between 1 and 5),
  velocidad real not null check (velocidad > 0),
  peso_seleccion real not null check (peso_seleccion > 0),
  sprite text,
  datos jsonb not null default '{}'::jsonb
);
create table public.capturas_usuario (
  usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
  pez_id bigint not null references public.peces(id),
  cantidad_capturada integer not null default 1 check (cantidad_capturada > 0),
  mejor_calidad_id text not null default 'comun',
  mejor_precio integer not null default 0,
  primera_captura timestamptz not null default now(),
  primary key (usuario_id, pez_id)
);
create table public.inventario_peces (
  id bigint generated always as identity primary key,
  usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
  pez_id bigint not null references public.peces(id),
  calidad_id text not null check (calidad_id in ('comun','poco_comun','raro','epico','legendario')),
  captura_riesgo boolean not null default false,
  precio integer not null check (precio > 0),
  creado_en timestamptz not null default now()
);
create index inventario_usuario_idx on public.inventario_peces(usuario_id);
create table public.eventos_captura (
  usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
  token uuid not null,
  inventario_id bigint,
  precio integer not null,
  creado_en timestamptz not null default now(),
  primary key (usuario_id, token)
);
create table public.preguntas_chatbot (
  id bigint generated always as identity primary key,
  usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
  pregunta text not null check (char_length(pregunta) between 1 and 300),
  respuesta text not null check (char_length(respuesta) <= 10000),
  creado_en timestamptz not null default now()
);
create index preguntas_usuario_idx on public.preguntas_chatbot(usuario_id);

create function public.bh_crear_perfil() returns trigger
language plpgsql security definer set search_path = '' as $$
begin
  insert into public.perfiles(usuario_id, usuario)
  values (new.id, left(coalesce(nullif(trim(new.raw_user_meta_data->>'usuario'),''), 'Pescador'),50))
  on conflict (usuario_id) do nothing;
  return new;
end;
$$;
create trigger bluehaven_perfil_nuevo after insert on auth.users
for each row execute function public.bh_crear_perfil();
insert into public.perfiles(usuario_id,usuario)
select id,left(coalesce(nullif(trim(raw_user_meta_data->>'usuario'),''),'Pescador'),50)
from auth.users on conflict (usuario_id) do nothing;

alter table public.perfiles enable row level security;
alter table public.peces enable row level security;
alter table public.capturas_usuario enable row level security;
alter table public.inventario_peces enable row level security;
alter table public.eventos_captura enable row level security;
alter table public.preguntas_chatbot enable row level security;
create policy perfil_propio on public.perfiles for select to authenticated using (usuario_id = (select auth.uid()));
create policy catalogo_autenticado on public.peces for select to authenticated using (true);
create policy capturas_propias on public.capturas_usuario for select to authenticated using (usuario_id = (select auth.uid()));
create policy inventario_propio on public.inventario_peces for select to authenticated using (usuario_id = (select auth.uid()));
create policy eventos_propios on public.eventos_captura for select to authenticated using (usuario_id = (select auth.uid()));
create policy preguntas_propias on public.preguntas_chatbot for select to authenticated using (usuario_id = (select auth.uid()));
revoke all on public.perfiles, public.peces, public.capturas_usuario, public.inventario_peces, public.eventos_captura, public.preguntas_chatbot from anon, authenticated;
grant select on public.perfiles, public.peces, public.capturas_usuario, public.inventario_peces, public.eventos_captura, public.preguntas_chatbot to authenticated;

create function public.bh_estado() returns jsonb
language plpgsql security invoker set search_path = '' as $$
declare uid uuid := auth.uid(); perfil jsonb; catalogo jsonb; mochila jsonb;
begin
  if uid is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  select to_jsonb(p) into perfil from public.perfiles p where usuario_id=uid;
  if perfil is null then raise exception 'No se encontró tu perfil.'; end if;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',p.id,'nombre',p.nombre,'rareza',p.rareza,'velocidad',p.velocidad,
    'pesoSeleccion',p.peso_seleccion,'sprite',p.sprite,'datos',p.datos,
    'descubierto',c.usuario_id is not null,'cantidad_capturada',coalesce(c.cantidad_capturada,0),
    'mejorCalidadId',c.mejor_calidad_id,'mejorPrecio',c.mejor_precio
  ) order by p.id),'[]'::jsonb) into catalogo
  from public.peces p left join public.capturas_usuario c on c.pez_id=p.id and c.usuario_id=uid;
  select coalesce(jsonb_agg(jsonb_build_object(
    'id',i.id,'pez_id',p.id,'nombre',p.nombre,'rareza',p.rareza,'sprite',p.sprite,
    'calidadId',i.calidad_id,'capturaRiesgo',i.captura_riesgo,'precio',i.precio
  ) order by i.id),'[]'::jsonb) into mochila
  from public.inventario_peces i join public.peces p on p.id=i.pez_id where i.usuario_id=uid;
  return jsonb_build_object('perfil',perfil,'catalogo',catalogo,'inventario',mochila);
end;
$$;

create function public.bh_guardar_captura(p_pez_id bigint,p_calidad text,p_riesgo boolean,p_token uuid) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid(); especie public.peces; previo public.eventos_captura;
  valor integer; multiplicador numeric; item_id bigint; cantidad integer;
begin
  if uid is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  if p_token is null or p_calidad is null or p_riesgo is null then raise exception 'Captura inválida.' using errcode='22023'; end if;
  perform 1 from public.perfiles where usuario_id=uid for update;
  if not found then raise exception 'Perfil inexistente.'; end if;
  select * into previo from public.eventos_captura where usuario_id=uid and token=p_token;
  if found then return jsonb_build_object('ok',true,'inventario_id',previo.inventario_id,'precio',previo.precio); end if;
  select * into especie from public.peces where id=p_pez_id;
  if not found then raise exception 'Especie inexistente.' using errcode='22023'; end if;
  multiplicador := case p_calidad when 'comun' then 1 when 'poco_comun' then 1.5 when 'raro' then 2.25 when 'epico' then 3.5 when 'legendario' then 5.5 end;
  if multiplicador is null then raise exception 'Calidad inválida.' using errcode='22023'; end if;
  valor := round((case especie.rareza when 1 then 50 when 2 then 120 when 3 then 300 when 4 then 800 when 5 then 2000 end) * multiplicador * (case when p_riesgo then 1.4 else 1 end));
  insert into public.capturas_usuario(usuario_id,pez_id,mejor_calidad_id,mejor_precio)
  values(uid,p_pez_id,p_calidad,valor)
  on conflict (usuario_id,pez_id) do update set
    cantidad_capturada=public.capturas_usuario.cantidad_capturada+1,
    mejor_calidad_id=case when excluded.mejor_precio > public.capturas_usuario.mejor_precio then excluded.mejor_calidad_id else public.capturas_usuario.mejor_calidad_id end,
    mejor_precio=greatest(public.capturas_usuario.mejor_precio,excluded.mejor_precio);
  select count(*) into cantidad from public.inventario_peces where usuario_id=uid;
  if cantidad < 10 then
    insert into public.inventario_peces(usuario_id,pez_id,calidad_id,captura_riesgo,precio)
    values(uid,p_pez_id,p_calidad,p_riesgo,valor) returning id into item_id;
  end if;
  insert into public.eventos_captura(usuario_id,token,inventario_id,precio) values(uid,p_token,item_id,valor);
  return jsonb_build_object('ok',true,'inventario_id',item_id,'precio',valor);
end;
$$;

create function public.bh_vender_pez(p_inventario_id bigint) returns jsonb
language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid(); valor integer; saldo bigint;
begin
  if uid is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  perform 1 from public.perfiles where usuario_id=uid for update;
  delete from public.inventario_peces where id=p_inventario_id and usuario_id=uid returning precio into valor;
  if valor is null then raise exception 'Ese pez ya no está en tu mochila.' using errcode='22023'; end if;
  update public.perfiles set dinero=dinero+valor where usuario_id=uid returning dinero into saldo;
  return jsonb_build_object('ok',true,'precio',valor,'dinero',saldo);
end;
$$;
create function public.bh_vender_todos() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid(); valor bigint; saldo bigint;
begin
  if uid is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  perform 1 from public.perfiles where usuario_id=uid for update;
  with vendidos as (delete from public.inventario_peces where usuario_id=uid returning precio)
    select coalesce(sum(precio),0) into valor from vendidos;
  update public.perfiles set dinero=dinero+valor where usuario_id=uid returning dinero into saldo;
  return jsonb_build_object('ok',true,'total',valor,'dinero',saldo);
end;
$$;
create function public.bh_comprar_cana() returns jsonb
language plpgsql security definer set search_path = '' as $$
declare uid uuid := auth.uid(); perfil public.perfiles;
begin
  if uid is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  select * into perfil from public.perfiles where usuario_id=uid for update;
  if not found then raise exception 'Perfil inexistente.'; end if;
  if perfil.tiene_bambu then return jsonb_build_object('ok',true,'dinero',perfil.dinero); end if;
  if perfil.dinero < 150 then raise exception 'Necesitás $150 para la caña.' using errcode='22023'; end if;
  update public.perfiles set dinero=dinero-150,tiene_bambu=true where usuario_id=uid;
  return jsonb_build_object('ok',true,'dinero',perfil.dinero-150);
end;
$$;
create function public.bh_registrar_pregunta(p_pregunta text,p_respuesta text) returns void
language plpgsql security definer set search_path = '' as $$
begin
  if auth.uid() is null then raise exception 'Iniciá sesión para continuar.' using errcode='28000'; end if;
  insert into public.preguntas_chatbot(usuario_id,pregunta,respuesta) values(auth.uid(),p_pregunta,p_respuesta);
end;
$$;
revoke all on function public.bh_crear_perfil() from public, anon, authenticated;
revoke all on function public.bh_estado(),public.bh_guardar_captura(bigint,text,boolean,uuid),public.bh_vender_pez(bigint),public.bh_vender_todos(),public.bh_comprar_cana(),public.bh_registrar_pregunta(text,text) from public,anon;
grant execute on function public.bh_estado(),public.bh_guardar_captura(bigint,text,boolean,uuid),public.bh_vender_pez(bigint),public.bh_vender_todos(),public.bh_comprar_cana(),public.bh_registrar_pregunta(text,text) to authenticated;

-- Catálogo generado desde catalogo.js: ver scripts/generar-semilla.cjs.

-- Catálogo Blue Haven. Ejecutar después de la migración de estructura.
insert into public.peces(nombre,rareza,velocidad,peso_seleccion,sprite,datos)
select p->>'nombre',(p->>'rareza')::int,(p->>'velocidad')::real,(p->>'pesoSeleccion')::real,p->>'sprite',p
from jsonb_array_elements($catalogo$[{"nombre":"Carpa","nombreCientifico":"Cyprinus carpio","rareza":1,"sprite":"Carpa.svg","habitat":"Aguas tranquilas de lagos y ríos lentos","alimentacion":"Omnívoro: plantas, insectos, gusanos","tamaño":"30-50 cm","peso":"1-3 kg","dificultad":"Fácil","descripcion":"La carpa es un pez resistente y común en aguas dulces. Es ideal para principiantes.","ceboRecomendado":"Lombriz o masa","datoCurioso":"Puede vivir hasta 20 años en condiciones ideales.","velocidad":1,"pesoSeleccion":55},{"nombre":"Trucha Arcoíris","nombreCientifico":"Oncorhynchus mykiss","rareza":2,"sprite":"Trucha.svg","habitat":"Ríos y arroyos de aguas frías y oxigenadas","alimentacion":"Carnívoro: insectos, pequeños peces, crustáceos","tamaño":"25-40 cm","peso":"0.5-2 kg","dificultad":"Media","descripcion":"Conocida por su coloración iridiscente. Es un pez deportivo muy valorado.","ceboRecomendado":"Mosca o cucharilla","datoCurioso":"Su nombre proviene de la franja rosada que recorre su costado.","velocidad":1.8,"pesoSeleccion":22},{"nombre":"Atún","nombreCientifico":"Thunnus thynnus","rareza":2,"sprite":"Atun.png","habitat":"Aguas abiertas del océano","alimentacion":"Carnívoro: peces pequeños, calamares, crustáceos","tamaño":"50-100 cm","peso":"5-20 kg","dificultad":"Media","descripcion":"Un nadador veloz y poderoso. Requiere equipo resistente.","ceboRecomendado":"Señuelo artificial","datoCurioso":"Puede nadar a 70 km/h y sumergirse a 1000 metros.","velocidad":2.3,"pesoSeleccion":18},{"nombre":"Pez Globo","nombreCientifico":"Tetraodontidae","rareza":2,"sprite":"Pez_Globo.png","habitat":"Aguas costeras tropicales y arrecifes poco profundos","alimentacion":"Invertebrados: caracoles, cangrejos y erizos","tamaño":"15-35 cm","peso":"0.4-1.5 kg","dificultad":"Media","descripcion":"Se infla ingiriendo agua para triplicar su tamaño ante cualquier peligro y disuadir atacantes.","ceboRecomendado":"Camarón o trozo de molusco","datoCurioso":"Posee tetrodotoxina, un veneno letal