","rareza":5,"sprite":"Pez_remo.svg","habitat":"Aguas profundas del océano (200-1000m)","alimentacion":"Carnívoro: krill, pequeños peces, calamares","tamaño":"300-800 cm","peso":"20-50 kg","dificultad":"Extrema","descripcion":"El pez óseo más largo del mundo. Vive en las profundidades abisales.","ceboRecomendado":"???","datoCurioso":"Es considerado el origen de las leyendas de serpientes marinas.","velocidad":4.2,"pesoSeleccion":1}]$catalogo$::jsonb) p
on conflict(nombre) do update set rareza=excluded.rareza,velocidad=excluded.velocidad,peso_seleccion=excluded.peso_seleccion,sprite=excluded.sprite,datos=excluded.datos;

commit;

begin;
create schema if not exists bluehaven_privado;
revoke all on schema bluehaven_privado from public,anon,authenticated;
alter table public.perfiles add column equipamiento jsonb not null default '{"cana":"basica","cebo":"sin_cebo","anzuelo":"simple"}'::jsonb;
create table public.productos_pesca (
 id text primary key, categoria text not null check(categoria in ('cana','cebo','anzuelo')),
 nombre text not null, precio integer not null check(precio>=0),unidades integer not null check(unidades>0),
 consumible boolean not null default false,descripcion text not null,efectos jsonb not null default '{}'::jsonb
);
create table public.equipo_usuario (
 usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
 producto_id text not null references public.productos_pesca(id),cantidad integer not null check(cantidad>=0),
 primary key(usuario_id,producto_id)
);
create index equipo_producto_idx on public.equipo_usuario(producto_id);
create table public.compras_pesca (
 usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,token uuid not null,
 producto_id text not null references public.productos_pesca(id),creado_en timestamptz not null default now(),
 primary key(usuario_id,token)
);
create index compras_producto_idx on public.compras_pesca(producto_id);
alter table public.productos_pesca enable row level security;
alter table public.equipo_usuario enable row level security;
alter table public.compras_pesca enable row level security;
create policy catalogo_equipo on public.productos_pesca for select to authenticated using(true);
create policy equipo_propio on public.equipo_usuario for select to authenticated using(usuario_id=(select auth.uid()));
create policy compras_propias on public.compras_pesca for select to authenticated using(usuario_id=(select auth.uid()));
revoke all on public.productos_pesca,public.equipo_usuario,public.compras_pesca from public,anon,authenticated;
grant select on public.productos_pesca,public.equipo_usuario,public.compras_pesca to authenticated;
-- PRODUCTOS_GENERADOS
insert into public.productos_pesca select p.id,p.categoria,p.nombre,p.precio,p.unidades,p.consumible,p.descripcion,p.efectos from jsonb_to_recordset($productos$[{"id":"basica","categoria":"cana","nombre":"Caña básica","precio":0,"unidades":1,"consumible":false,"descripcion":"Tu equipo inicial. Sin bonificaciones.","efectos":{}},{"id":"bambu","categoria":"cana","nombre":"Caña de Bambú","precio":150,"unidades":1,"consumible":false,"descripcion":"Minijuegos un 15% más fáciles.","efectos":{"dificultad":0.85}},{"id":"metal","categoria":"cana","nombre":"Caña de Metal","precio":500,"unidades":1,"consumible":false,"descripcion":"Minijuegos un 25% más fáciles.","efectos":{"dificultad":0.75}},{"id":"sin_cebo","categoria":"cebo","nombre":"Sin cebo","precio":0,"unidades":1,"consumible":false,"descripcion":"Pesca sin gastar consumibles.","efectos":{}},{"id":"lombriz","categoria":"cebo","nombre":"Lombrices","precio":35,"unidades":5,"consumible":true,"descripcion":"5 lanzamientos. La picada llega un 30% antes.","efectos":{"espera":0.7}},{"id":"marisco","categoria":"cebo","nombre":"Mariscos","precio":75,"unidades":5,"consumible":true,"descripcion":"5 lanzamientos. Aumenta el peso de especies raras un 25% por nivel de rareza.","efectos":{"atraccion":0.25}},{"id":"simple","categoria":"anzuelo","nombre":"Anzuelo simple","precio":0,"unidades":1,"consumible":false,"descripcion":"Tu anzuelo inicial.","efectos":{}},{"id":"precision","categoria":"anzuelo","nombre":"Anzuelo de precisión","precio":90,"unidades":1,"consumible":false,"descripcion":"Tenés 0,15 segundos más para enganchar.","efectos":{"enganche":0.15}},{"id":"reforzado","categoria":"anzuelo","nombre":"Anzuelo reforzado","precio":200,"unidades":1,"consumible":false,"descripcion":"Reduce un 10% la dificultad del minijuego.","efectos":{"dificultad":0.9}}]$productos$::jsonb) as p(id text,categoria text,nombre text,precio integer,unidades integer,consumible boolean,descripcion text,efectos jsonb);
insert into public.equipo_usuario(usuario_id,producto_id,cantidad) select usuario_id,'bambu',1 from public.perfiles where tiene_bambu on conflict do nothing;
update public.perfiles set equipamiento=jsonb_set(equipamiento,'{cana}','"bambu"') where tiene_bambu;

create function bluehaven_privado.estado_tienda(uid uuid) returns jsonb language sql stable security definer set search_path='' as $$
 select jsonb_build_object(
 'dinero',p.dinero,'equipo',p.equipamiento,
 'objetos',jsonb_build_object('basica',1,'sin_cebo',1,'simple',1,'bambu',case when p.tiene_bambu then 1 else 0 end) ||
   coalesce((select jsonb_object_agg(e.producto_id,e.cantidad) from public.equipo_usuario e where e.usuario_id=uid),'{}'::jsonb),
 'productos',(select jsonb_agg(to_jsonb(a) order by a.categoria,a.precio,a.id) from public.productos_pesca a))
 from public.perfiles p where p.usuario_id=uid;
$$;
revoke all on function bluehaven_privado.estado_tienda(uuid) from public,anon,authenticated;

create function public.bh_tienda_estado() returns jsonb language plpgsql security definer set search_path='' as $$
begin
 if auth.uid() is null then raise exception 'Iniciá sesión.' using errcode='28000';end if;
 return bluehaven_privado.estado_tienda(auth.uid());
end;
$$;
create function public.bh_comprar_producto(p_producto_id text,p_token uuid) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();perfil public.perfiles;producto public.productos_pesca;anterior text;
begin
 if uid is null then raise exception 'Iniciá sesión.' using errcode='28000';end if;
 if p_token is null then raise exception 'Compra inválida.' using errcode='22023';end if;
 select * into perfil from public.perfiles where usuario_id=uid for update;
 if not found then raise exception 'Perfil inexistente.';end if;
 select producto_id into anterior from public.compras_pesca where usuario_id=uid and token=p_token;
 if found then
   if anterior<>p_producto_id then raise exception 'Identificador de compra ya utilizado.';end if;
   return bluehaven_privado.estado_tienda(uid);
 end if;
 select * into producto from public.productos_pesca where id=p_producto_id;
 if not found or producto.precio=0 then raise exception 'Artículo no disponible para comprar.' using errcode='22023';end if;
 if not producto.consumible and (exists(select 1 from public.equipo_usuario where usuario_id=uid and producto_id=p_producto_id and cantidad>0) or (p_producto_id='bambu' and perfil.tiene_bambu)) then
   raise exception 'Ya tenés este artículo.' using errcode='22023';
 end if;
 if perfil.dinero<producto.precio then raise exception 'No tenés suficiente dinero.' using errcode='22023';end if;
 update public.perfiles set dinero=dinero-producto.precio,tiene_bambu=tiene_bambu or p_producto_id='bambu' where usuario_id=uid;
 insert into public.equipo_usuario(usuario_id,producto_id,cantidad) values(uid,p_producto_id,producto.unidades)
 on conflict(usuario_id,producto_id) do update set cantidad=public.equipo_usuario.cantidad+excluded.cantidad;
 insert into public.compras_pesca(usuario_id,token,producto_id) values(uid,p_token,p_producto_id);
 return bluehaven_privado.estado_tienda(uid);
end;
$$;
create function public.bh_equipar_producto(p_producto_id text) returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();perfil public.perfiles;producto public.productos_pesca;
begin
 if uid is null then raise exception 'Iniciá sesión.' using errcode='28000';end if;
 select * into perfil from public.perfiles where usuario_id=uid for update;
 if not found then raise exception 'Perfil inexistente.';end if;
 select * into producto from public.productos_pesca where id=p_producto_id;
 if not found then raise exception 'Artículo inexistente.' using errcode='22023';end if;
 if producto.precio>0 and not exists(select 1 from public.equipo_usuario where usuario_id=uid and producto_id=p_producto_id and cantidad>0) and not(p_producto_id='bambu' and perfil.tiene_bambu) then
   raise exception 'Primero comprá este artículo.' using errcode='22023';
 end if;
 update public.perfiles set equipamiento=jsonb_set(equipamiento,array[producto.categoria],to_jsonb(p_producto_id)) where usuario_id=uid;
 return bluehaven_privado.estado_tienda(uid);
end;
$$;
create function public.bh_preparar_pesca() returns jsonb language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid();perfil public.perfiles;producto public.productos_pesca;efecto jsonb;
 dificultad numeric:=1;espera numeric:=1;enganche numeric:=0;atraccion numeric:=0;cebo text;cantidad_actual integer;
begin
 if uid is null then raise exception 'Iniciá sesión.' using errcode='28000';end if;
 select * into perfil from public.perfiles where usuario_id=uid for update;
 if not found then raise exception 'Perfil inexistente.';end if;
 cebo:=perfil.equipamiento->>'cebo';
 if cebo<>'sin_cebo' then
   select cantidad into cantidad_actual from public.equipo_usuario where usuario_id=uid and producto_id=cebo;
   if coalesce(cantidad_actual,0)<1 then cebo:='sin_cebo';perfil.equipamiento:=jsonb_set(perfil.equipamiento,'{cebo}','"sin_cebo"');end if;
 end if;
 for producto in select * from public.productos_pesca where id in(perfil.equipamiento->>'cana',cebo,perfil.equipamiento->>'anzuelo') loop
   efecto:=producto.efectos;
   dificultad:=dificultad*coalesce((efecto->>'dificultad')::numeric,1);
   espera:=espera*coalesce((efecto->>'espera')::numeric,1);
   enganche:=enganche+coalesce((efecto->>'enganche')::numeric,0);
   atraccion:=atraccion+coalesce((efecto->>'atraccion')::numeric,0);
 end loop;
 if cebo<>'sin_cebo' then
   update public.equipo_usuario set cantidad=cantidad-1 where usuario_id=uid and producto_id=cebo returning cantidad into cantidad_actual;
   if cantidad_actual=0 then perfil.equipamiento:=jsonb_set(perfil.equipamiento,'{cebo}','"sin_cebo"');end if;
 end if;
 update public.perfiles set equipamiento=perfil.equipamiento where usuario_id=uid;
 return jsonb_build_object('estado',bluehaven_privado.estado_tienda(uid),'efectos',jsonb_build_object('dificultad',dificultad,'espera',espera,'enganche',enganche,'atraccion',atraccion));
end;
$$;
revoke all on function public.bh_tienda_estado(),public.bh_comprar_producto(text,uuid),public.bh_equipar_producto(text),public.bh_preparar_pesca() from public,anon;
grant execute on function public.bh_tienda_estado(),public.bh_comprar_producto(text,uuid),public.bh_equipar_producto(text),public.bh_preparar_pesca() to authenticated;
commit;

-- Filtros para nuevas cuentas y cambios de email/nombre. Conserva cuentas y progreso existentes.
begin;
create function bluehaven_privado.normalizar_texto(texto text) returns text language sql immutable set search_path='' as $$
 select translate(lower(regexp_replace(normalize(coalesce(texto,''),NFKD),U&'[\0300-\036f\200B-\200D\FEFF]','','g')),'013457@$!','oieastasi');
$$;
create function bluehaven_privado.texto_ofensivo(texto text) returns boolean language plpgsql immutable set search_path='' as $$
declare token text; prohibidas text[]:=array['puto','puta','putos','putas','mierda','mierdas','carajo','carajos','cabron','cabrona','cabrones','boludo','boluda','boludos','boludas','pelotudo','pelotuda','pelotudos','pelotudas','pendejo','pendeja','pendejos','pendejas','gilipollas','maricon','maricones','hdp','hijodeputa','hijadeputa','conchadetumadre','forro','forra','forros','forras','imbecil','imbeciles','idiota','idiotas','estupido','estupida','estupidos','estupidas','fuck','fucker','fucking','shit','bitch','asshole'];
begin
 for token in select regexp_split_to_table(coalesce(texto,''),'[^[:alnum:]@$!]+') loop
  if bluehaven_privado.normalizar_texto(token)=any(prohibidas) or bluehaven_privado.normalizar_texto(regexp_replace(token,'^[0-9]+|[0-9]+$','','g'))=any(prohibidas) then return true;end if;
 end loop;
 return regexp_replace(bluehaven_privado.normalizar_texto(texto),'[^a-z]','','g')=any(prohibidas);
end;
$$;
create function bluehaven_privado.validar_email(texto text) returns void language plpgsql immutable set search_path='' as $f$
declare email text:=lower(trim(coalesce(texto,''))); dominio text:=split_part(email,'@',2); nombre text:=split_part(email,'@',1);
begin
 if length(email)>254 or length(nombre)>64 or email!~$re$^[a-z0-9!#$%&'*+\-/=?^_`{|}~]+(?:\.[a-z0-9!#$%&'*+\-/=?^_`{|}~]+)*@[a-z0-9.-]+$$re$ then raise exception 'Ingresá un email válido.' using errcode='23514';end if;
 if not (dominio=any(array['gmail.com','googlemail.com','hotmail.com','hotmail.es','hotmail.com.ar','outlook.com','outlook.es','outlook.com.ar','live.com','live.com.ar','live.com.mx','msn.com','yahoo.com','yahoo.es','yahoo.com.ar','yahoo.com.mx','ymail.com','rocketmail.com','icloud.com','me.com','mac.com','proton.me','protonmail.com','pm.me','aol.com','gmx.com','gmx.net','mail.com','zoho.com'])) then raise exception 'Proveedor de correo no permitido.' using errcode='23514';end if;
 if bluehaven_privado.texto_ofensivo(nombre) then raise exception 'El correo contiene palabras no permitidas.' using errcode='23514';end if;
end;
$f$;
create function bluehaven_privado.validar_nombre(texto text) returns void language plpgsql immutable set search_path='' as $$
begin
 if texto is null or length(trim(texto)) not between 1 and 50 then raise exception 'El nombre debe tener entre 1 y 50 caracteres.' using errcode='23514';end if;
 if bluehaven_privado.texto_ofensivo(texto) then raise exception 'Elegí un nombre sin palabras ofensivas.' using errcode='23514';end if;
end;
$$;
create function bluehaven_privado.validar_cuenta_auth() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='INSERT' then
  perform bluehaven_privado.validar_email(new.email);
  perform bluehaven_privado.validar_nombre(coalesce(nullif(trim(new.raw_user_meta_data->>'usuario'),''),'Pescador'));
 else
  if coalesce(new.email_change,'')<>'' and new.email_change is distinct from old.email_change then perform bluehaven_privado.validar_email(new.email_change);end if;
  if new.email is distinct from old.email then perform bluehaven_privado.validar_email(new.email);end if;
  if new.raw_user_meta_data->>'usuario' is distinct from old.raw_user_meta_data->>'usuario' then perform bluehaven_privado.validar_nombre(coalesce(nullif(trim(new.raw_user_meta_data->>'usuario'),''),'Pescador'));end if;
 end if;
 return new;
end;
$$;
create trigger bluehaven_validar_cuenta before insert or update of email,email_change,raw_user_meta_data on auth.users for each row execute function bluehaven_privado.validar_cuenta_auth();
create function bluehaven_privado.validar_nombre_perfil() returns trigger language plpgsql set search_path='' as $$
begin
 if TG_OP='INSERT' then perform bluehaven_privado.validar_nombre(new.usuario);
 elsif new.usuario is distinct from old.usuario then perform bluehaven_privado.validar_nombre(new.usuario);end if;
 return new;
end;
$$;
create trigger bluehaven_validar_nombre before insert or update of usuario on public.perfiles for each row execute function bluehaven_privado.validar_nombre_perfil();
revoke all on function bluehaven_privado.normalizar_texto(text),bluehaven_privado.texto_ofensivo(text),bluehaven_privado.validar_email(text),bluehaven_privado.validar_nombre(text),bluehaven_privado.validar_cuenta_auth(),bluehaven_privado.validar_nombre_perfil() from public,anon,authenticated;
grant usage on schema bluehaven_privado to supabase_auth_admin;
grant execute on function bluehaven_privado.normalizar_texto(text),bluehaven_privado.texto_ofensivo(text),bluehaven_privado.validar_email(text),bluehaven_privado.validar_nombre(text),bluehaven_privado.validar_cuenta_auth() to supabase_auth_admin;
commit;

-- Proyección pública mínima del ranking; los perfiles e inventarios siguen privados.
begin;
lock table public.perfiles,public.capturas_usuario in share row exclusive mode;
create table bluehaven_privado.ranking_pesca (
 usuario_id uuid primary key references public.perfiles(usuario_id) on delete cascade,
 usuario text not null,
 dinero bigint not null default 0 check(dinero>=0),
 capturas bigint not null default 0 check(capturas>=0)
);
alter table bluehaven_privado.ranking_pesca enable row level security;
revoke all on bluehaven_privado.ranking_pesca from public,anon,authenticated;
create index ranking_dinero_idx on bluehaven_privado.ranking_pesca(dinero desc,capturas desc,usuario_id);
create index ranking_capturas_idx on bluehaven_privado.ranking_pesca(capturas desc,dinero desc,usuario_id);
insert into bluehaven_privado.ranking_pesca(usuario_id,usuario,dinero,capturas)
 select p.usuario_id,p.usuario,p.dinero,coalesce(c.total,0) from public.perfiles p
 left join (select usuario_id,sum(cantidad_capturada)::bigint total from public.capturas_usuario group by usuario_id)c using(usuario_id);
create function bluehaven_privado.actualizar_ranking_perfil() returns trigger
language plpgsql security definer set search_path='' as $$
begin
 insert into bluehaven_privado.ranking_pesca(usuario_id,usuario,dinero) values(new.usuario_id,new.usuario,new.dinero)
 on conflict(usuario_id) do update set usuario=excluded.usuario,dinero=excluded.dinero;
 return new;
end;
$$;
create trigger bluehaven_ranking_perfil after insert or update of dinero,usuario on public.perfiles for each row execute function bluehaven_privado.actualizar_ranking_perfil();
create function bluehaven_privado.actualizar_ranking_captura() returns trigger
language plpgsql security definer set search_path='' as $$
declare uid uuid;
begin
 if TG_OP='DELETE' then uid=old.usuario_id;else uid=new.usuario_id;end if;
 update bluehaven_privado.ranking_pesca set capturas=coalesce((select sum(cantidad_capturada) from public.capturas_usuario where usuario_id=uid),0) where usuario_id=uid;
 if TG_OP='DELETE' then return old;end if;
 return new;
end;
$$;
create trigger bluehaven_ranking_captura after insert or update or delete on public.capturas_usuario for each row execute function bluehaven_privado.actualizar_ranking_captura();
revoke all on function bluehaven_privado.actualizar_ranking_perfil(),bluehaven_privado.actualizar_ranking_captura() from public,anon,authenticated;
create function bluehaven_privado.leer_ranking(p_criterio text default 'dinero') returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare orden text;respuesta jsonb;
begin
 if p_criterio='dinero' then orden='dinero desc,capturas desc,usuario_id';
 elsif p_criterio='capturas' then orden='capturas desc,dinero desc,usuario_id';
 else raise exception 'Clasificación inválida.' using errcode='22023';end if;
 -- orden proviene exclusivamente de las dos constantes anteriores, nunca del cliente.
 execute 'with puestos as (select usuario_id,usuario,dinero,capturas,row_number() over(order by '||orden||') puesto from bluehaven_privado.ranking_pesca), filas as (select puesto,case when bluehaven_privado.texto_ofensivo(usuario) then ''Pescador'' else usuario end nombre,dinero,capturas,coalesce(usuario_id=auth.uid(),false) es_tuyo from puestos) select jsonb_build_object(''jugadores'',coalesce((select jsonb_agg(to_jsonb(t) order by puesto) from (select * from filas order by puesto limit 20)t),''[]''::jsonb),''tu_puesto'',(select to_jsonb(f) from filas f where es_tuyo),''total_jugadores'',(select count(*) from puestos))' into respuesta;
 return respuesta;
end;
$$;
revoke all on function bluehaven_privado.leer_ranking(text) from public;
grant usage on schema bluehaven_privado to anon,authenticated;
grant execute on function bluehaven_privado.leer_ranking(text) to anon,authenticated;
create function public.bh_ranking(p_criterio text default 'dinero') returns jsonb
language sql stable security invoker set search_path='' as $$ select bluehaven_privado.leer_ranking(p_criterio); $$;
revoke all on function public.bh_ranking(text) from public;
grant execute on function public.bh_ranking(text) to anon,authenticated;
commit;

-- Denegación explícita como defensa ante futuros grants accidentales.
-- Solo las funciones internas del propietario leen o escriben esta proyección.
begin;
create policy ranking_solo_funciones_internas on bluehaven_privado.ranking_pesca
 for all to anon,authenticated using(false) with check(false);
commit;

-- Salas privadas: membresía autoritativa; las posiciones efímeras viajan por Realtime.
begin;
create table bluehaven_privado.salas (
 id uuid primary key default gen_random_uuid(),
 codigo text not null unique default upper(substr(replace(gen_random_uuid()::text,'-',''),1,12)),
 vence timestamptz not null default now()+interval '24 hours'
);
create table bluehaven_privado.sala_jugadores (
 usuario_id uuid primary key references public.perfiles(usuario_id) on delete cascade,
 sala_id uuid not null references bluehaven_privado.salas(id) on delete cascade,
 id uuid not null unique default gen_random_uuid(),
 cliente uuid not null,
 asiento smallint not null check(asiento between 0 and 3),
 visto timestamptz not null default now(),
 unique(sala_id,asiento)
);
alter table bluehaven_privado.salas enable row level security;
alter table bluehaven_privado.sala_jugadores enable row level security;
revoke all on bluehaven_privado.salas,bluehaven_privado.sala_jugadores from public,anon,authenticated;
create policy salas_solo_funciones on bluehaven_privado.salas as restrictive for all to anon,authenticated using(false) with check(false);
create policy miembros_solo_funciones on bluehaven_privado.sala_jugadores as restrictive for all to anon,authenticated using(false) with check(false);
create function bluehaven_privado.gestionar_sala(p_accion text,p_codigo text,p_cliente uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); miembro bluehaven_privado.sala_jugadores; sala bluehaven_privado.salas; asiento_libre int;
begin
 if uid is null or p_cliente is null then raise exception 'Iniciá sesión para jugar en una sala.' using errcode='42501';end if;
 if p_accion not in ('crear','unir','estado','salir') or p_accion is null then raise exception 'Acción de sala inválida.' using errcode='22023';end if;
 -- Una sola sesión por cuenta, incluso ante peticiones simultáneas.
 perform pg_advisory_xact_lock(hashtextextended('bh-sala:'||uid::text,0));
 select * into miembro from bluehaven_privado.sala_jugadores where usuario_id=uid;
 if p_accion='salir' then
  if miembro.cliente=p_cliente then
   perform 1 from bluehaven_privado.salas where id=miembro.sala_id for update;
   delete from bluehaven_privado.sala_jugadores where usuario_id=uid;
   delete from bluehaven_privado.salas s where s.id=miembro.sala_id and not exists(select 1 from bluehaven_privado.sala_jugadores m where m.sala_id=s.id);
  end if;
  return null;
 end if;
 if miembro.usuario_id is not null and (miembro.visto<now()-interval '75 seconds' or not exists(select 1 from bluehaven_privado.salas where id=miembro.sala_id and vence>now())) then
  delete from bluehaven_privado.sala_jugadores where usuario_id=uid;miembro:=null;
 end if;
 if miembro.usuario_id is not null then
  if miembro.cliente<>p_cliente then raise exception 'Tu cuenta ya está en una sala en otra pestaña. Salí allí o esperá 75 segundos.' using errcode='P0001';end if;
  if p_accion='unir' and not exists(select 1 from bluehaven_privado.salas where id=miembro.sala_id and codigo=upper(regexp_replace(p_codigo,'[ -]','','g'))) then raise exception 'Primero salí de tu sala actual.' using errcode='P0001';end if;
  select * into sala from bluehaven_privado.salas where id=miembro.sala_id for update;
 elsif p_accion='estado' then
  raise exception 'La sala se cerró o venció tu conexión. Podés volver a unirte.' using errcode='P0002';
 else
  if p_accion='crear' then
   -- Limpieza acotada de salas vencidas; SKIP LOCKED no bloquea otras admisiones.
   delete from bluehaven_privado.salas where id in(select id from bluehaven_privado.salas where vence<now() order by vence limit 50 for update skip locked);
   insert into bluehaven_privado.salas default values returning * into sala;
  else
   if p_codigo is null or upper(regexp_replace(p_codigo,'[ -]','','g')) !~ '^[0-9A-F]{12}$' then raise exception 'Usá el código de 12 caracteres de la sala.' using errcode='22023';end if;
   select * into sala from bluehaven_privado.salas where codigo=upper(regexp_replace(p_codigo,'[ -]','','g')) and vence>now() for update;
   if sala.id is null then raise exception 'No encontramos esa sala. Revisá el código o pedí uno nuevo.' using errcode='P0002';end if;
  end if;
  delete from bluehaven_privado.sala_jugadores where sala_id=sala.id and visto<now()-interval '75 seconds';
  select n into asiento_libre from generate_series(0,3)n where not exists(select 1 from bluehaven_privado.sala_jugadores m where m.sala_id=sala.id and m.asiento=n) order by n limit 1;
  if asiento_libre is null then raise exception 'La sala está llena (4 jugadores).' using errcode='P0001';end if;
  insert into bluehaven_privado.sala_jugadores(usuario_id,sala_id,cliente,asiento) values(uid,sala.id,p_cliente,asiento_libre) returning * into miembro;
 end if;
 update bluehaven_privado.sala_jugadores set visto=now() where usuario_id=uid;
 return jsonb_build_object('codigo',sala.codigo,'canal','bh-sala:'||sala.id::text,'yo',miembro.id,'vence',sala.vence,'jugadores',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'nombre',case when bluehaven_privado.texto_ofensivo(p.usuario) then 'Pescador' else p.usuario end,'asiento',m.asiento) order by m.asiento) from bluehaven_privado.sala_jugadores m join public.perfiles p using(usuario_id) where m.sala_id=sala.id and m.visto>now()-interval '75 seconds'),'[]'::jsonb));
end;
$$;
revoke all on function bluehaven_privado.gestionar_sala(text,text,uuid) from public,anon;
grant execute on function bluehaven_privado.gestionar_sala(text,text,uuid) to authenticated;
create function public.bh_sala(p_accion text,p_codigo text default '',p_cliente uuid default null) returns jsonb
language sql security invoker set search_path='' as $$ select bluehaven_privado.gestionar_sala(p_accion,p_codigo,p_cliente); $$;
revoke all on function public.bh_sala(text,text,uuid) from public,anon;
grant execute on function public.bh_sala(text,text,uuid) to authenticated;
create function bluehaven_privado.puede_entrar_sala(p_canal text) returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select 1 from bluehaven_privado.sala_jugadores m join bluehaven_privado.salas s on s.id=m.sala_id where m.usuario_id=(select auth.uid()) and 'bh-sala:'||s.id::text=p_canal and m.visto>now()-interval '75 seconds' and s.vence>now());
$$;
revoke all on function bluehaven_privado.puede_entrar_sala(text) from public,anon;
grant execute on function bluehaven_privado.puede_entrar_sala(text) to authenticated;
-- El stack mínimo de API local no trae Realtime. En Supabase estas tablas existen.
do $$ begin
 if to_regclass('realtime.messages') is not null then
  execute 'create policy bluehaven_sala_recibir on realtime.messages for select to authenticated using (extension in (''broadcast'',''presence'') and (select bluehaven_privado.puede_entrar_sala((select realtime.topic()))))';
  execute 'create policy bluehaven_sala_enviar on realtime.messages for insert to authenticated with check (extension in (''broadcast'',''presence'') and (select bluehaven_privado.puede_entrar_sala((select realtime.topic()))))';
 end if;
end $$;
commit;

-- Orden consistente al recuperar una membresía vencida.
begin;
create or replace function bluehaven_privado.gestionar_sala(p_accion text,p_codigo text,p_cliente uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); miembro bluehaven_privado.sala_jugadores; sala bluehaven_privado.salas; asiento_libre int;
begin
 if uid is null or p_cliente is null then raise exception 'Iniciá sesión para jugar en una sala.' using errcode='42501';end if;
 if p_accion not in ('crear','unir','estado','salir') or p_accion is null then raise exception 'Acción de sala inválida.' using errcode='22023';end if;
 -- Solo las admisiones/salidas se serializan entre salas; los latidos son independientes.
 -- Evita invertir bloqueos al trasladar una membresía vencida a otra sala.
 if p_accion<>'estado' then perform pg_advisory_xact_lock(hashtextextended('bh-sala-admisiones',0));end if;
 -- Una sola sesión por cuenta, incluso ante peticiones simultáneas.
 perform pg_advisory_xact_lock(hashtextextended('bh-sala:'||uid::text,0));
 select * into miembro from bluehaven_privado.sala_jugadores where usuario_id=uid;
 if p_accion='salir' then
  if miembro.cliente=p_cliente then
   perform 1 from bluehaven_privado.salas where id=miembro.sala_id for update;
   delete from bluehaven_privado.sala_jugadores where usuario_id=uid;
   delete from bluehaven_privado.salas s where s.id=miembro.sala_id and not exists(select 1 from bluehaven_privado.sala_jugadores m where m.sala_id=s.id);
  end if;
  return null;
 end if;
 if miembro.usuario_id is not null and (miembro.visto<now()-interval '75 seconds' or not exists(select 1 from bluehaven_privado.salas where id=miembro.sala_id and vence>now())) then
  if p_accion='estado' then raise exception 'La sala se cerró o venció tu conexión. Podés volver a unirte.' using errcode='P0002';end if;
  delete from bluehaven_privado.sala_jugadores where usuario_id=uid;miembro:=null;
 end if;
 if miembro.usuario_id is not null then
  if miembro.cliente<>p_cliente then raise exception 'Tu cuenta ya está en una sala en otra pestaña. Salí allí o esperá 75 segundos.' using errcode='P0001';end if;
  if p_accion='unir' and not exists(select 1 from bluehaven_privado.salas where id=miembro.sala_id and codigo=upper(regexp_replace(p_codigo,'[ -]','','g'))) then raise exception 'Primero salí de tu sala actual.' using errcode='P0001';end if;
  select * into sala from bluehaven_privado.salas where id=miembro.sala_id for update;
 elsif p_accion='estado' then
  raise exception 'La sala se cerró o venció tu conexión. Podés volver a unirte.' using errcode='P0002';
 else
  if p_accion='crear' then
   -- Limpieza acotada de salas vencidas; SKIP LOCKED no bloquea otras admisiones.
   delete from bluehaven_privado.salas where id in(select id from bluehaven_privado.salas where vence<now() order by vence limit 50 for update skip locked);
   insert into bluehaven_privado.salas default values returning * into sala;
  else
   if p_codigo is null or upper(regexp_replace(p_codigo,'[ -]','','g')) !~ '^[0-9A-F]{12}$' then raise exception 'Usá el código de 12 caracteres de la sala.' using errcode='22023';end if;
   select * into sala from bluehaven_privado.salas where codigo=upper(regexp_replace(p_codigo,'[ -]','','g')) and vence>now() for update;
   if sala.id is null then raise exception 'No encontramos esa sala. Revisá el código o pedí uno nuevo.' using errcode='P0002';end if;
  end if;
  delete from bluehaven_privado.sala_jugadores where sala_id=sala.id and visto<now()-interval '75 seconds';
  select n into asiento_libre from generate_series(0,3)n where not exists(select 1 from bluehaven_privado.sala_jugadores m where m.sala_id=sala.id and m.asiento=n) order by n limit 1;
  if asiento_libre is null then raise exception 'La sala está llena (4 jugadores).' using errcode='P0001';end if;
  insert into bluehaven_privado.sala_jugadores(usuario_id,sala_id,cliente,asiento) values(uid,sala.id,p_cliente,asiento_libre) returning * into miembro;
 end if;
 update bluehaven_privado.sala_jugadores set visto=now() where usuario_id=uid;
 return jsonb_build_object('codigo',sala.codigo,'canal','bh-sala:'||sala.id::text,'yo',miembro.id,'vence',sala.vence,'jugadores',coalesce((select jsonb_agg(jsonb_build_object('id',m.id,'nombre',case when bluehaven_privado.texto_ofensivo(p.usuario) then 'Pescador' else p.usuario end,'asiento',m.asiento) order by m.asiento) from bluehaven_privado.sala_jugadores m join public.perfiles p using(usuario_id) where m.sala_id=sala.id and m.visto>now()-interval '75 seconds'),'[]'::jsonb));
end;
$$;
commit;

begin;
alter table bluehaven_privado.sala_jugadores add column ultimo_mensaje timestamptz not null default '-infinity';
create table bluehaven_privado.sala_mensajes(
 id uuid primary key,
 sala_id uuid not null references bluehaven_privado.salas(id) on delete cascade,
 usuario_id uuid not null references public.perfiles(usuario_id) on delete cascade,
 nombre text not null,
 texto text not null check(char_length(texto) between 1 and 280),
 fecha timestamptz not null default clock_timestamp()
);
create index sala_mensajes_recientes on bluehaven_privado.sala_mensajes(sala_id,fecha desc,id);
alter table bluehaven_privado.sala_mensajes enable row level security;
revoke all on bluehaven_privado.sala_mensajes from public,anon,authenticated;
create policy chat_solo_funciones on bluehaven_privado.sala_mensajes as restrictive for all to anon,authenticated using(false) with check(false);
create function bluehaven_privado.chat_sala(p_cliente uuid,p_texto text,p_token uuid) returns jsonb
language plpgsql security definer set search_path='' as $$
declare uid uuid:=auth.uid(); m bluehaven_privado.sala_jugadores; texto text; anterior bluehaven_privado.sala_mensajes;
begin
 if uid is null or p_cliente is null then raise exception 'Iniciá sesión para usar el chat.' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended('bh-sala:'||uid::text,0));
 select * into m from bluehaven_privado.sala_jugadores where usuario_id=uid and cliente=p_cliente and visto>now()-interval '75 seconds';
 if m.usuario_id is null then raise exception 'Necesitás estar conectado a una sala para usar el chat.' using errcode='42501';end if;
 perform 1 from bluehaven_privado.salas where id=m.sala_id and vence>now() for update;
 if not found then raise exception 'La sala venció. Volvé a unirte.' using errcode='42501';end if;
 if p_texto is not null then
  if p_token is null or char_length(p_texto)>280 then raise exception 'El mensaje admite hasta 280 caracteres.' using errcode='22023';end if;
  texto:=trim(regexp_replace(p_texto,'[[:cntrl:]]',' ','g'));
  if char_length(texto)<1 then raise exception 'Escribí un mensaje.' using errcode='22023';end if;
  if bluehaven_privado.texto_ofensivo(texto) then raise exception 'El mensaje contiene palabras no permitidas.' using errcode='23514';end if;
  select * into anterior from bluehaven_privado.sala_mensajes where id=p_token;
  if anterior.id is not null then
   if anterior.usuario_id<>uid or anterior.sala_id<>m.sala_id or anterior.texto<>texto then raise exception 'El identificador del mensaje ya fue utilizado.' using errcode='22023';end if;
  else
   if m.ultimo_mensaje>clock_timestamp()-interval '1 second' then raise exception 'Esperá un segundo antes de enviar otro mensaje.' using errcode='P0001';end if;
   insert into bluehaven_privado.sala_mensajes(id,sala_id,usuario_id,nombre,texto)
   select p_token,m.sala_id,uid,case when bluehaven_privado.texto_ofensivo(p.usuario) then 'Pescador' else p.usuario end,texto from public.perfiles p where usuario_id=uid;
   update bluehaven_privado.sala_jugadores set ultimo_mensaje=clock_timestamp() where usuario_id=uid;
   delete from bluehaven_privado.sala_mensajes where sala_id=m.sala_id and id not in(select id from bluehaven_privado.sala_mensajes where sala_id=m.sala_id order by fecha desc,id limit 50);
   -- Solo una señal sin texto: el receptor consulta la RPC autenticada para verificar autor y sala.
   if to_regprocedure('realtime.send(jsonb,text,text,boolean)') is not null then
    execute 'select realtime.send($1,$2,$3,$4)' using '{}'::jsonb,'chat_aviso','bh-sala:'||m.sala_id::text,true;
   end if;
  end if;
 end if;
 return coalesce((select jsonb_agg(jsonb_build_object('id',msg.id,'nombre',msg.nombre,'texto',msg.texto,'fecha',msg.fecha,'es_tuyo',msg.usuario_id=uid) order by msg.fecha,msg.id) from bluehaven_privado.sala_mensajes msg where msg.sala_id=m.sala_id),'[]'::jsonb);
end;
$$;
revoke all on function bluehaven_privado.chat_sala(uuid,text,uuid) from public,anon;
grant execute on function bluehaven_privado.chat_sala(uuid,text,uuid) to authenticated;
create function public.bh_sala_chat(p_cliente uuid,p_texto text default null,p_token uuid default null) returns jsonb
language sql security invoker set search_path='' as $$ select bluehaven_privado.chat_sala(p_cliente,p_texto,p_token); $$;
revoke all on function public.bh_sala_chat(uuid,text,uuid) from public,anon;
grant execute on function public.bh_sala_chat(uuid,text,uuid) to authenticated;
commit;
